import subprocess
import sys
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("recruiting")


@mcp.tool()
def run_resume_parser_job(resume_path: str, parser_script: str = "scripts/parse_resume.py") -> str:
    p = subprocess.run(
        [sys.executable, parser_script, resume_path],
        capture_output=True,
        text=True,
        timeout=120,
    )
    if p.returncode != 0:
        return "Parser failed: " + p.stderr.strip()
    return p.stdout.strip()
